do local _E = (getgenv and getgenv()) or _G if not _E["LPH_NO_VIRTUALIZE"] then local id = function(f) return f end _E["LPH_NO_VIRTUALIZE"] = id _E["LPH_JIT_MAX"] = id _E["LPH_JIT"] = id _E["LPH_ENCFUNC"] = id _E["LPH_ENCSTR"] = function(s) return s end _E["LPH_CRASH"] = function() end end end local NAME = "PracticalBasketball" local CIPHER = "" return function(Lib, Core) if type(Core) ~= "table" or type(Core.__unlock) ~= "function" then return end local U32 = 4294967296 local NX = {} for a = 0, 15 do for b = 0, 15 do local r, x, y, p, t = 0, a, b, 1, 0 while t < 4 do local xb, yb = x % 2, y % 2 if xb ~= yb then r = r + p end x = (x - xb) / 2; y = (y - yb) / 2; p = p * 2; t = t + 1 end NX[a * 16 + b] = r end end local function bxb(a, b) return NX[((a - a % 16) / 16) * 16 + (b - b % 16) / 16] * 16 + NX[(a % 16) * 16 + (b % 16)] end local function bxor(a, b) a = a % U32; b = b % U32 local r, mul, t = 0, 1, 0 while t < 4 do local ab, bb = a % 256, b % 256 r = r + bxb(ab, bb) * mul a = (a - ab) / 256; b = (b - bb) / 256; mul = mul * 256; t = t + 1 end return r end local function mul32(a, b) a = a % U32; b = b % U32 local ah = (a - a % 65536) / 65536 local al = a % 65536 return (((ah * b) % 65536) * 65536 + al * b) % U32 end local function shr(x, n) local d, k = 1, 0 while k < n do d = d * 2; k = k + 1 end return (x - (x % d)) / d end local function rotl(x, n) x = x % U32 local pow, k = 1, 0 while k < n do pow = pow * 2; k = k + 1 end local left = mul32(x, pow) local dp; dp = 1; k = 0 while k < (32 - n) do dp = dp * 2; k = k + 1 end local right = (x - (x % dp)) / dp return (left + right) % U32 end local function chash(str, seed) local h = (2166136261 + (seed or 0)) % U32 local acc = 5381 local i, n = 1, #str while i <= n do local c = string.byte(str, i) h = bxor(h, c) h = mul32(h, 16777619) acc = (mul32(acc, 33) + c + i) % U32 h = bxor(h, rotl(acc, (c % 23) + 1)) h = rotl(h, (i % 13) + 3) i = i + 1 end h = bxor(h, shr(h, 16)) h = mul32(h, 2246822519) h = bxor(h, shr(h, 13)) h = mul32(h, 3266489917) h = bxor(h, shr(h, 16)) return h end local HEX = "0123456789abcdef" local function tohex(v) local s, i = "", 0 while i < 8 do local nib = v % 16 v = (v - nib) / 16 s = string.sub(HEX, nib + 1, nib + 1) .. s i = i + 1 end return s end local function deriveKey(master, name) local base = master .. "\0" .. name .. "\0syllinse" local k, round = "", 0 while round < 8 do k = k .. tohex(chash(base .. "|" .. round, mul32(round, 2654435761))) round = round + 1 end return k end local keystream = LPH_NO_VIRTUALIZE(function(key, length) local s = chash(key, 0) if s == 0 then s = 2654435761 end local out, pd = {}, 0 while pd < length do s = bxor(s, mul32(s, 8192)) s = bxor(s, (s - s % 131072) / 131072) s = bxor(s, mul32(s, 32)) s = s % U32 local t = s local b1 = t % 256; t = (t - b1) / 256 local b2 = t % 256; t = (t - b2) / 256 local b3 = t % 256; t = (t - b3) / 256 local b4 = t pd = pd + 1; out[pd] = b1 if pd >= length then break end pd = pd + 1; out[pd] = b2 if pd >= length then break end pd = pd + 1; out[pd] = b3 if pd >= length then break end pd = pd + 1; out[pd] = b4 end return out end) local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/" local B64R = {} for i = 1, #B64 do B64R[string.byte(B64, i)] = i - 1 end local b64decode = LPH_NO_VIRTUALIZE(function(s) local out, oc = {}, 0 local acc, bits = 0, 0 for i = 1, #s do local ch = string.byte(s, i) if ch ~= 61 then local v = B64R[ch] if v then acc = acc * 64 + v bits = bits + 6 if bits >= 8 then bits = bits - 8 local div = 1 local kk = 0 while kk < bits do div = div * 2; kk = kk + 1 end local byte = (acc - acc % div) / div acc = acc % div oc = oc + 1; out[oc] = byte end end end end return out end) local decrypt = LPH_NO_VIRTUALIZE(function(bytes, key) local n = #bytes local ks = keystream(key, n) local pieces, pc, i = {}, 0, 1 while i <= n do local e = i + 4095; if e > n then e = n end local buf = {} for k = i, e do buf[k - i + 1] = bxb(bytes[k], ks[k]) end pc = pc + 1; pieces[pc] = string.char(table.unpack(buf)) i = e + 1 if Core.__yield then pcall(Core.__yield) end end return table.concat(pieces) end) local masked = Core.__unlock(NAME) if type(masked) ~= "string" then return end local pad = deriveKey(Core.__n, NAME) local key = {} for i = 1, #masked do local a = string.byte(masked, i) local b = string.byte(pad, ((i - 1) % #pad) + 1) key[i] = string.char(bxor(a, b)) end key = table.concat(key) local src = decrypt(b64decode(CIPHER), key) local fn = loadstring(src) if type(fn) ~= "function" then return end local inner = fn() if type(inner) == "function" then return inner(Lib, Core) end return inner end